draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // book
  ctx.fillStyle = 'brown';
  ctx.fillRect(W/2-50, H/2-50, 100, 100);
  ctx.strokeRect(W/2-50, H/2-50, 100, 100);

  // stick figure
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2+120, 20, 0, 2*Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2+100);
  ctx.lineTo(W/2, H/2+150);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2+120);
  ctx.lineTo(W/2-30, H/2+90);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2+120);
  ctx.lineTo(W/2+30, H/2+90);
  ctx.stroke();

  // applying wisdom
  ctx.fillStyle = 'blue';
  ctx.beginPath();
  ctx.arc(W/2+70, H/2+70, 10+10*Math.sin(t), 0, 2*Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W/2+70, H/2+60);
  ctx.lineTo(W/2+100, H/2+40);
  ctx.stroke();

  ctx.restore();
}
